"""Big QYL Windows-VM deployment bundle - UI Automation build (bounded search + real cell clicks).

Usage in VM:  py deploy_to_vm.py
Writes the agent's Python files into the current directory (overwrites same
names). Standard library only; verifies SHA-256 after writing each file.

Needs installed in the VM (request via FTP/SMB):  uiautomation, pyautogui.
pywinauto is NOT required. If uiautomation is missing, the agent still runs on
keyboard / fallback paths.
"""
import base64
import hashlib
import os
import sys
import zlib

FILES = [
    ('ui_find.py', 21496, '698c50d1', ''),
    ('calc_nav.py', 9255, '959b9139', ''),
    ('human_io.py', 18535, '12da6d8d', ''),
    ('office_worker.py', 15733, 'e12e8681', ''),
    ('spreadsheet_part1.py', 7573, '986164f3', ''),
    ('spreadsheet_part2.py', 7273, 'deb3c587', ''),
    ('spreadsheet_part3.py', 6455, '5e587362', ''),
    ('spreadsheet_part4.py', 8399, '9cbb7c4c', ''),
    ('research_notes_part1.py', 11097, 'e44a0b4b', ''),
    ('research_notes_part2.py', 5281, 'aa6b6be2', ''),
    ('financial_report.py', 36157, '0d0f79e0', ''),
    ('web_tasks.py', 54733, '34dab1bb', ''),
    ('market_capture.py', 9341, 'dbc5c95d', ''),
    ('orchestrator.py', 23102, '0210096b', ''),
    ('diag_uia.py', 9537, 'f07ff283', ''),
]

def main():
    bad = 0
    for name, size, digest, payload in FILES:
        try:
            data = zlib.decompress(base64.b64decode("".join(payload.split())))
            with open(name, "wb") as f:
                f.write(data)
            with open(name, "rb") as f:
                written = f.read()
            ok = len(written) == size and hashlib.sha256(written).hexdigest()[:8] == digest
        except Exception as error:
            print(f"ERROR {name}: {error!r}")
            ok = False
        print(("OK       " if ok else "MISMATCH ") + name)
        bad += not ok
    print(f"{len(FILES) - bad}/{len(FILES)} files OK in {os.getcwd()}")
    return 1 if bad else 0

if __name__ == "__main__":
    sys.exit(main())
